input.sparql:
SELECT ?zone ?zoneLabel ?point ?ps ?tsid WHERE {
  ?zone brick:hasSubclass* ?z .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  ?point brick:hasPropertyOf ?zone ; a ?pc .
  FILTER (rdf:type(?pc) = brick:Temperature)
  ?point ref:hasExternalReference ?ps .
  ?point ref:hasTimeseriesId ?tsid .
}
